package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.common.order.StatementOrder;
import org.junit.jupiter.api.Test;

class LmdbDirectAdjacencySpillSortIteratorTest {

	@Test
	void primitiveBufferIsChargedAndReleasedOnEarlyClose() {
		String property = "rdf4j.lmdb.nativeSort.maxBytes";
		String previous = System.getProperty(property);
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.process();
		long usedBefore = memory.usedBytes();
		try {
			System.setProperty(property, "64");
			try (RecordIterator sorted = new LmdbDirectAdjacencySpillSortIterator(rows(16), StatementOrder.C)) {
				assertThat(sorted.next()).isNotNull();
				assertThat(memory.usedBytes()).isGreaterThan(usedBefore);
			}
			assertThat(memory.usedBytes()).isEqualTo(usedBefore);
		} finally {
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
	}

	private static RecordIterator rows(int count) {
		return new RecordIterator() {
			private int next;

			@Override
			public long[] next() {
				if (next >= count) {
					return null;
				}
				int value = count - next++;
				return new long[] { value, 1L, value + 100L, value & 1 };
			}

			@Override
			public void close() {
			}
		};
	}
}
